fn prompt_yes_no_loop(
    term: &Term,
    options: &[PromptOption],
    sel: &mut usize,
    pad: &str,
    active_prefix: &Style,
    active_style: &Style,
    inactive_prefix: &Style,
    inactive_style: &Style,
    prompt: &Prompt,
