    term.write_line(&prompt.question).map_err(BivvyError::Io)?;
    term.hide_cursor().map_err(BivvyError::Io)?;

    let result = prompt_yes_no_loop(term, options, &mut sel, &pad, &active_prefix, &active_style, &inactive_prefix, &inactive_style, prompt);

    // Always restore cursor, even on error
    let _ = term.show_cursor();

    result
}

/// Inner loop for yes/no prompt, separated so the caller can ensure cursor cleanup.
fn prompt_yes_no_loop(
    term: &Term,
    options: &[PromptOption],
    sel: &mut usize,
    pad: &str,
    active_prefix: &Style,
    active_style: &Style,
    inactive_prefix: &Style,
    inactive_style: &Style,
    prompt: &Prompt,
) -> Result<PromptResult> {
    loop {
        // Draw option lines
        for (i, opt) in options.iter().enumerate() {
            let line = if i == *sel {
                format!(
                    "{}{} {}",
                    pad,
                    active_prefix.apply_to("›"),
                    active_style.apply_to(&opt.label)
                )
            } else {
                format!(
                    "{}{} {}",
                    pad,
                    inactive_prefix.apply_to("·"),
                    inactive_style.apply_to(&opt.label)
                )
            };
            term.write_line(&line).map_err(BivvyError::Io)?;
        }
        term.flush().map_err(BivvyError::Io)?;

