}

fn prompt_confirm(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    let default = prompt
        .default
        .as_ref()
        .map(|s| s.to_lowercase() == "true" || s == "y" || s == "yes")
        .unwrap_or(true);

    let result = Confirm::new()
        .with_prompt(&prompt.question)
        .default(default)
        .interact_on(term)
        .map_err(map_dialoguer_err);

    // Restore cursor in case dialoguer left it hidden on error (e.g. Ctrl+D / EOF)
    if result.is_err() {
        let _ = term.show_cursor();
    }

    Ok(PromptResult::Bool(result?))
}

fn prompt_input(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    let input = Input::<String>::new().with_prompt(&prompt.question);

    let result = if let Some(default) = &prompt.default {
        input
            .default(default.clone())
            .interact_on(term)
            .map_err(map_dialoguer_err)
    } else {
        input.interact_on(term).map_err(map_dialoguer_err)
    };

    // Restore cursor in case dialoguer left it hidden on error (e.g. Ctrl+D / EOF)
    if result.is_err() {
        let _ = term.show_cursor();
    }

    Ok(PromptResult::String(result?))
}

